package com.tuckersoft.branchengine.entity;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="playthroughs") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Playthrough { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(unique=true,nullable=false,length=40) private String playerTag; @ManyToOne(optional=false) private User user; @Column(nullable=false) private String startNodeCode; @ManyToOne(optional=false) private StoryNode currentNode; @Column(nullable=false) private Integer lucidity; @Column(nullable=false) private Integer controlLevel; @Column(nullable=false) private String status; private String endingCode; @Column(nullable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; @OneToMany(mappedBy="playthrough") @Builder.Default private List<Decision> decisions=new ArrayList<>(); }
